	"880": {
		"cId": "880",
		"name": {
			"nominative": "Venerable John the Disciple of the Venerable Gregory of Decapolis (9<sup>th</sup> C)",
			"short": "Venerable John"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "Adorning thy life with abstinence, O father, * thou didst mortify thy flesh; * wherefore, thou didst vanquish the attacks of the enemy, O all-blessed John, * and hast passed over to God, * to life everlasting free from sorrow, as a worthy heir. ** Pray thou to Him, that we be saved."
			}
		]
	},
