	"2292": {
		"cId": "2292",
		"name": {
			"nominative": "Apostle Philip, of the 70, one of the 7 Deacons (1<sup>st</sup> C)",
			"short": "Apostle Philip"
		},
		"scriptures": [
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Acts_8:26-39",
				"pericope": "20"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Lk_10:1-15",
				"pericope": "50"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "<p>O holy Apostle Philip, pray to unto the merciful God, that He may grant remission of transgressions unto our souls.</p>"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "<p>Today Philip, forechosen from among the apostles, grantest a wealth of healing to the world. He is the most wondrous fisherman of the nations, a converser with the disciples of Christ. He protectest those who praise Him from all evil. Therefore we cry out unto him: O, Apostle, save us all by thy prayers. </p>"
			}
		]
	},
