	"3248": {
		"cId": "3248",
		"name": {
			"nominative": "Venerable Akakios of Sinai, mentioned in The Ladder (6<sup>th</sup> C)",
			"short": "Venerable Akakios"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "O God of our fathers, * deal with us ever according to Thy meekness. * Deprive us not of Thy mercy, * but through their supplications ** direct our life in peace."
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "Forsaking the world, thou didst follow Christ from childhood, * O all-wise and venerable Acacius, * and, emulating His voluntary humility, * thou didst cast down the prideful tyrant. ** Pray thou unceasingly in behalf of us all."
			}
		]
	},
