	"4320": {
		"cId": "4320",
		"name": {
			"nominative": "Apostles of the 70 and Deacons: Prochorus, Nicanor, Timon and Parmenas (1<sup>st</sup> C)",
			"short": "Apostles"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "<p>O holy apostles * entreat the merciful God ** that He grant to our souls remission of transgressions.</p>"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "1",
				"body": "The glorious Nicanor, Prochorus, Parmenus and Timon, * the honored deacons and eye-witnesses to the Word, * have been shown to be chosen vessels of the Faith. * Wherefore, we celebrate your sacred memory today, ** blessing you in gladness of heart."
			}
		]
	},
