	"4397": {
		"cId": "4397",
		"name": {
			"nominative": "Saint Emilian the Confessor, Bishop of Cyzicus († c. 815-820)",
			"short": "Saint Emilian"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "Chanting, the Church, for which thou didst suffer, O Emilian, doth glorify thee who didst show thyself to be a mighty champion of the Trinity. Wherefore, we honor thy memory. Deliver thy servants from the invasion of the heathen."
			}
		]
	},
