	"4619": {
		"cId": "4619",
		"name": {
			"nominative": "Apostles of the 70: Stachias, Amplias, Urban, Narcissos, Apellias and Aristoboulos (1<sup>st</sup> C)",
			"short": "Apostles of"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "<p>O Holy Apostles, pray to the merciful God that He may grant our souls remission of offenses.</p>"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "0",
				"body": "<p>As sacred treasuries of the All Holy Spirit, and radiances of the Glorious Sun, let us dutifully hymn the wise Apostles: Apelles, Urban and Aristobulus, Amplius, Narcissus and Stachys, whom the grace of our God hath gathered together.</p>"
			}
		]
	},
