	"9904": {
		"cId": "9904",
		"name": {
			"nominative": "Sunday after Nativity: Saints Joseph the Betrothed, David the King, and James the Brother of the Lord",
			"short": "Sunday after Nativity"
		},
		"scriptures": [
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Gal_1:11-19",
				"pericope": "200"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Mt_2:13-23",
				"pericope": "4"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "Proclaim the wonder, O Joseph,  * to David, the ancestor of God:  * thou didst see a Virgin great with Child,  * thou gavest glory with the shepherds,  * thou worshipped with the Magi,  * thou received the news from the angel.  * Pray to Christ God to save our souls!"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"podoben": "1",
				"body": "Today godly David is filled with joy;  * Joseph and James offer praise.  * The glorious crown of their kinship with Christ fills them with great joy.  * They sing praises to the One ineffably born on earth,  * and they cry out: “O Compassionate One, save those who honor Thee!”"
			}
		]
	},
