	"76401": {
		"cId": "76401",
		"name": {
			"nominative": "Holy Prophet Elisha (9<sup>th</sup> C BC)",
			"short": "Prophet"
		},
		"scriptures": [
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Jas_5:10-20",
				"pericope": "57"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Lk_4:22b-30",
				"pericope": "14"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "The angel in the flesh, the foundation of the prophets, the second forerunner of the coming of Christ, the glorious Elijah from on high sent down grace upon Elisha to dispel infirmities and to cleanse lepers. Wherefore, he poureth forth healings upon those who honor him."
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "Thou wast shown to be a prophet of God, receiving a twofold measure of grace, which truly befitted thee, O blessed Elisha; for thou wast the companion of Elijah, and with him dost unceasingly entreat Christ God in behalf of us all."
			}
		]
	},
