	"91547": {
		"cId": "91547",
		"name": {
			"nominative": "Commemoration of the Miracle of the Archangel Michael at Chonah (4<sup>th</sup> C)",
			"short": "Archangel"
		},
		"scriptures": [
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Heb_2:2-10",
				"pericope": "305",
				"note": "for the Archangel"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Lk_10:16-21",
				"pericope": "51",
				"note": "for the Archangel"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "<p>Supreme commander of the armies of Heaven, * we, the unworthy, do ever entreat thee, * that by thy prayers thou dost ever surround us * with the protection of the wings of thine immaterial glory, * preserving us that earnestly fall down before thee and cry aloud: * Deliver us from misfortunes, ** in that thou art the leader of the hosts on high.</p>"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "<p>O chief commander of God, * minister of glory divine, * captain of the angels and instructor of men: * beg thou great mercy and that which is profitable for us, ** for thou art the supreme commander of the bodiless hosts.</p>"
			}
		]
	},
