	"96201": {
		"cId": "96201",
		"name": {
			"nominative": "Holy Apostle and Evangelist John the Theologian († 98-117)"
		},
		"scriptures": [
			{
				"service": "vespers",
				"type": "1",
				"reading": "I Jn_3:21-4:6"
			},
			{
				"service": "vespers",
				"type": "2",
				"reading": "I Jn_4:11-16"
			},
			{
				"service": "vespers",
				"type": "3",
				"reading": "I Jn_4:20-5:5"
			},
			{
				"service": "matins",
				"type": "1",
				"reading": "Jn_21:15-25",
				"pericope": "67",
				"cmd": "dow != 0"
			},
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "I Jn_1:1-7",
				"pericope": "68"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Jn_19:25-27, 21:24-25",
				"pericope": "61"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "O beloved apostle of Christ God, haste thou to deliver a defenseless people. He Who permitted thee to recline against His breast receiveth thee, prostrate in supplication. Him do thou beseech, O theologian, that He dispel the gloom of the nations which doth beset us, asking for us peace and great mercy."
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "Who can recount thy mighty works, O virgin apostle * For thou pourest out miracles and dost cause healings to flow forth; and thou prayest for our souls, in that thou art a theologian and the friend of Christ."
			}
		]
	},
