	"152501": {
		"cId": "152501",
		"name": {
			"nominative": "Holy Equal-to-the-Apostles Methodius († 885) and Cyrill († 869), teachers of the Slavs [from Monday]"
		},
		"scriptures": [
			{
				"service": "matins",
				"type": "1",
				"reading": "Jn_10:9-16"
			},
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Heb_7:26-8:2",
				"pericope": "318"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Mt_5:14-19",
				"pericope": "11"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "In that ye share the ways of the apostles, O divinely wise Cyril and Methodius, ye teachers of the Slavic lands, entreat the Master of all, that He confirm all the Slavic nations in Orthodoxy and oneness of mind, grant peace to the world and save our souls."
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "Let us honor our two sacred enlighteners, who poured forth upon us a spring of divine knowledge through their translation of the divine Scriptures. Drawing forth abundantly therefrom to this very day, we bless you, O Cyril and Methodius, who stand before the throne of the Most High and fervently pray for our souls."
			}
		]
	},
