	"205102": {
		"cId": "205102",
		"name": {
			"nominative": "Holy Protomartyr and Archdeacon Stephen († c.34)",
			"short": "Protomartyr"
		},
		"scriptures": [
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Acts_6:8-15, 7:1-5, 7:47-60",
				"pericope": "17"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Mt_21:33-42",
				"pericope": "87"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "Thou didst fight the good fight, and, didst denounce the impiety of the tyrants, * O protomartyr and apostle of Christ; * for, stoned at the hands of the iniquitous, * thou hast received from on high a crown from the right hand of the Lord, ** and didst exclaim to God, crying aloud: O Lord, lay not this sin to their charge!"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "Yesterday the Master came to us in the flesh, * and today his servant departeth from the flesh. * Yesterday He that reigneth over the flesh was born, * and today his servant is slain by stoning. ** For His sake the godly protomartyr Stephen doth meet his end."
			}
		]
	},
