	"220201": {
		"cId": "220201",
		"name": {
			"nominative": "Venerable Theodore the Confessor, Abbot of the Studion († 826)",
			"short": "Venerable Theodore"
		},
		"scriptures": [
			{
				"service": "liturgy",
				"type": "apostol",
				"reading": "Heb_13:17-21",
				"pericope": "335"
			},
			{
				"service": "liturgy",
				"type": "gospel",
				"reading": "Mt_4:25-5:12a",
				"pericope": "10"
			}
		],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "0",
				"body": "O instructor of Orthodoxy, teacher of piety and purity, * beacon for the whole world, divinely inspired adornment of monastics. * O most wise Theodore by thy doctrines thou hast illumined all. ** O harp of the Spirit, entreat Christ God that our souls be saved."
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "Thine angelic life of fasting * thou didst adorn with the struggles of suffering, * O divinely blessed Theodore, * and thou hast been shown to abide with the angels. ** With them cease thou never to pray to Christ God for us all."
			}
		]
	},
