	"248801": {
		"cId": "248801",
		"name": {
			"nominative": "Martyrs Galaction and his wife Epistimia, at Emesa (3<sup>rd</sup> C)",
			"short": "Martyrs Galaction"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"body": "Thy martyrs, O Lord, through their sufferings have received incorruptible crowns from Thee, our God. For having Thy strength, they despoiled their adversaries, and shattered the powerless audacity of demons. Through their intercessions, save Thou our souls!"
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "2",
				"body": "Thou hast been counted among the ranks of the martyrs of Christ, having fought valiantly, thou brightly struggled, O glorious Galaction, with thine honourable wife and fellow sufferer, Epistime; pray ye unceasingly to the one God for us all."
			}
		]
	},
