	"09279": {
		"cId": "09279",
		"name": {
			"nominative": "Apostles of the Seventy: Archippus and Philemon, and martyred Equal-to-the-Apostles Apphia (1<sup>st</sup> C)",
			"short": "Apostles"
		},
		"scriptures": [],
		"hymns": [
			{
				"kind": "troparion",
				"service": "liturgy",
				"type": "1",
				"tone": "3",
				"body": "O holy apostle Archippus * entreat the merciful God ** that He grant to our souls remission of transgressions."
			},
			{
				"kind": "kontakion",
				"service": "liturgy",
				"type": "1",
				"tone": "4",
				"podoben": "1",
				"body": "The Church, possessing thee as a great star, * O Archippus, * and illumined by the rays of thy miracles, * crieth out to thee: ** Save those who honor thy memory with faith!"
			}
		]
	},
